declare(strict_types=1); require __DIR__.'/koneksi.php'; require_once __DIR__.'/fungsi/auth.php'; require_once __DIR__.'/fungsi/alur-persetujuan-izin.php'; wajibRole('pic','koordinator','manager','direktur','admin','superadmin');
$where=roleOperasional()?'d.department_id = '.(int)departmentIdPengguna():'1=1'; $data=mysqli_query($conn,"SELECT d.id,d.nominal,d.deskripsi,d.status,d.created_at,k.emp_id,k.employee_name FROM denda_reports d INNER JOIN karyawan k ON k.id=d.karyawan_id WHERE {$where} ORDER BY d.created_at DESC LIMIT 100"); $judulHalaman='Notifikasi Denda'; $subjudulHalaman='Pengajuan denda dan perubahan status terbaru.'; $halamanAktif='denda'; require __DIR__.'/partials/atas.php'; ?>
